<template><div class="guide-page"><PageHead :title="flow?.title||'学习路线不存在'" :desc="flow?.goal||'请从学习首页重新选择路线。'"><router-link to="/guide?tab=learn"><el-button>全部路线</el-button></router-link></PageHead><template v-if="flow"><section class="panel"><h2>开始之前</h2><ul class="guide-prerequisites"><li v-for="(text,i) in flow.prerequisites" :key="i">{{text}}</li></ul><p class="guide-muted">已阅读 {{readCount}} / {{flow.steps.length}} · 已练习 {{practiceCount}} / {{flow.steps.length}}。打开文章不会自动标记完成。</p></section><div class="guide-learning-layout"><nav class="panel guide-learning-steps" aria-label="学习步骤"><button v-for="(step,i) in flow.steps" :key="step.id" :aria-current="step.id===selected?'step':undefined" @click="selected=step.id"><span>{{i+1}}. {{step.title}}</span><small>{{guide.progress.read[step.articleId]?'已读':'未读'}} · {{guide.progress.practiced[step.articleId]?'已练习':'未练习'}}</small></button></nav><section v-if="current" class="panel guide-learning-body"><h2>{{current.title}}</h2><div class="guide-practice"><strong>练习建议</strong><p>{{current.practice}}</p><ul><li v-for="(check,i) in current.checkpoints" :key="i">{{check}}</li></ul><router-link v-if="practiceAllowed" :to="current.route!"><el-button type="primary" plain>进入业务页练习</el-button></router-link><p v-else-if="current.route" class="guide-muted">当前身份无权进入此业务页，仍可阅读说明。</p></div><GuideArticleReader :article-id="current.articleId" anchor-prefix="learn" @open="openRelated" @home="router.push('/guide')"/><div class="guide-toolbar"><el-button :disabled="currentIndex===0" @click="move(-1)">上一步</el-button><el-button :disabled="currentIndex===flow.steps.length-1" @click="move(1)">下一步</el-button></div></section></div></template><el-empty v-else description="未找到学习路线"/></div></template>
<script setup lang="ts">
import '../../components/guide/guide.css'
import {computed,ref,watch} from 'vue'
import {useRoute,useRouter} from 'vue-router'
import PageHead from '../../components/PageHead.vue'
import GuideArticleReader from '../../components/guide/GuideArticleReader.vue'
import {guideFlows} from '../../domain/guide/registry'
import {useGuideStore} from '../../stores/guide'
import {useCatalogStore} from '../../stores/catalog'
const route=useRoute(),router=useRouter(),guide=useGuideStore(),catalog=useCatalogStore(),flow=computed(()=>guideFlows.find(f=>f.id===route.params.flowId)),selected=ref('')
watch(flow,value=>{selected.value=value?.steps.find(s=>!guide.progress.read[s.articleId])?.id||value?.steps[0]?.id||''},{immediate:true})
const current=computed(()=>flow.value?.steps.find(s=>s.id===selected.value)),currentIndex=computed(()=>flow.value?.steps.findIndex(s=>s.id===selected.value)??-1),readCount=computed(()=>flow.value?.steps.filter(s=>guide.progress.read[s.articleId]).length||0),practiceCount=computed(()=>flow.value?.steps.filter(s=>guide.progress.practiced[s.articleId]).length||0)
const practiceAllowed=computed(()=>{if(!current.value?.route)return false;try{const target=router.resolve(current.value.route);return catalog.canRoute({path:target.path,query:target.query})}catch{return false}})
function move(delta:number){const step=flow.value?.steps[currentIndex.value+delta];if(step){selected.value=step.id;window.scrollTo({top:0,behavior:'smooth'})}}
function openRelated(id:string){void router.push({path:`/guide/articles/${id}`,query:route.query.returnTo?{returnTo:String(route.query.returnTo)}:{}})}
</script>
<style>.guide-prerequisites{line-height:1.8;padding-left:20px}.guide-learning-layout{display:grid;grid-template-columns:240px minmax(0,1fr);gap:20px;align-items:start}.guide-learning-steps{position:sticky;top:12px;padding:12px!important}.guide-learning-steps button{display:block;width:100%;border:0;background:none;color:var(--el-text-color-primary);text-align:left;cursor:pointer;padding:12px;border-radius:4px;line-height:1.5}.guide-learning-steps button[aria-current=step]{background:var(--el-color-primary-light-9);color:var(--el-color-primary)}.guide-learning-steps small{display:block;font-size:12px;color:var(--text-secondary);margin-top:5px}.guide-learning-body{min-width:0}.guide-practice{padding:14px 18px;background:var(--el-fill-color-light);line-height:1.7;margin:18px 0 24px}.guide-practice p{margin:6px 0}.guide-practice ul{padding-left:20px;font-size:13px}@media(max-width:1000px){.guide-learning-layout{grid-template-columns:1fr}.guide-learning-steps{position:static;display:flex;overflow:auto}.guide-learning-steps button{width:200px;flex-shrink:0}}
</style>
